}
.btn-white:hover { background: #f0f0f0; text-decoration: none; }
.btn-sm { padding: 8px 16px; font-size: 13px; }
.btn-lg { padding: 16px 32px; font-size: 17px; }

/* ===== Product Icon Bar ===== */
.product-icon-bar {
