}

/* ===== Carousel ===== */
.carousel-container {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}
.carousel {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  padding: 0 24px;
