}
.carousel-arrow:disabled {
  opacity: 0;
  pointer-events: none;
}
.carousel-arrow-left { left: -10px; }
.carousel-arrow-right { right: -10px; }

/* ===== Product Card (Latest) ===== */
.product-card {
  width: 280px;
  padding: 28px 24px;
  background: var(--color-bg-white);
  border-radius: var(--radius-lg);
