.hero-tile--dark .hero-tile-tagline { color: rgba(255,255,255,0.7); }
.hero-tile--dark .hero-tile-link { color: #6bf; }
.hero-tile--green { background: linear-gradient(135deg, #d8f0dc 0%, #c5e8c9 50%, #b2dfb8 100%); }
.hero-tile--lavender { background: linear-gradient(135deg, #e8dff5 0%, #ddd2f0 50%, #d0c5eb 100%); }

/* ===== Accessories & Audio Cards ===== */
.accessory-card {
