  background: var(--color-bg-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth);
}
.diff-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.diff-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 4px;
}
.diff-card-name { font-size: 17px; font-weight: 600; }
.diff-card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
  flex: 1;
}
.diff-card-link {
  font-size: 14px;
  color: var(--color-accent);
  font-weight: 500;
}

/* ===== Brand Collab ===== */
.brand-collab {
  display: flex;
  align-items: center;
  gap: 60px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 40px 0;
}
.brand-collab-image {
  width: 300px;
  height: 300px;
  background: linear-gradient(135deg, #e8dff5, #fce4d6);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  flex-shrink: 0;
}
.brand-collab-content h3 {
  font-size: clamp(24px, 3.5vw, 36px);
  font-weight: 700;
  letter-spacing: -0.025em;
  margin-bottom: 12px;
}
.brand-collab-content p {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-bottom: 20px;
  max-width: 500px;
}

/* ===== Savings & Offers Cards ===== */
.savings-card {
  width: 280px;
  padding: 28px 24px;
  background: var(--color-bg-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth);
}
.savings-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.savings-card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}
.savings-card-name { font-size: 17px; font-weight: 600; }
.savings-card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
  flex: 1;
}
.savings-card-link {
  font-size: 14px;
  color: var(--color-accent);
  font-weight: 500;
}

/* ===== Quick Links ===== */
.quick-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  max-width: var(--max-width);
  margin: 0 auto;
}
.quick-link-btn {
  padding: 12px 28px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
  background: var(--color-bg);
  color: var(--color-dark);
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
  text-decoration: none;
}
.quick-link-btn:hover { background: #e8e8ed; text-decoration: none; }

/* ===== Entertainment Tabs ===== */
.entertainment-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}
.entertainment-tab {
  padding: 10px 24px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
  background: transparent;
  color: var(--color-dark);
  border: 1px solid var(--color-border);
  cursor: pointer;
  transition: all var(--transition-fast);
  letter-spacing: -0.01em;
}
.entertainment-tab:hover { background: rgba(0,0,0,0.04); }
.entertainment-tab.active {
  background: var(--color-dark);
  color: #fff;
  border-color: var(--color-dark);
}
.entertainment-content { display: none; }
.entertainment-content.active { display: block; }
.entertainment-card {
  width: 200px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.entertainment-card-image {
  width: 180px;
  height: 260px;
  background: var(--color-bg);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}
.entertainment-card-title {
  font-size: 14px;
  font-weight: 600;
}
.entertainment-card-cta {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-accent);
}

/* ===== Category Page Specific ===== */
.category-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg-white);
}
.category-hero-title {
  font-size: clamp(36px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 12px;
}
.category-hero-subtitle {
  font-size: clamp(17px, 2.5vw, 21px);
  color: var(--color-text-secondary);
  font-weight: 450;
}

/* Sticky section nav */
.section-nav {
  position: sticky;
  top: 48px;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  z-index: 50;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  display: flex;
  gap: 0;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  justify-content: center;
}
.section-nav-link {
  padding: 14px 20px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  letter-spacing: -0.01em;
}
.section-nav-link:hover { color: var(--color-dark); text-decoration: none; }
.section-nav-link.active {
  color: var(--color-dark);
  border-bottom-color: var(--color-dark);
}

/* ===== Model Card (Category Pages) ===== */
.model-card {
  width: 260px;
  padding: 28px 24px;
  background: var(--color-bg-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth);
}
.model-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.model-card-image {
  width: 140px;
  height: 140px;
  background: var(--color-bg);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
  margin-bottom: 8px;
}
.model-card-name { font-size: 17px; font-weight: 600; }
.model-card-price { font-size: 15px; font-weight: 500; }
.model-card-monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
}
.model-card-badge {
  font-size: 11px;
  font-weight: 600;
  color: var(--color-badge-new);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.model-card-btn {
  margin-top: 8px;
  padding: 8px 20px;
  border-radius: 980px;
  font-size: 14px;
  font-weight: 500;
  background: var(--color-accent);
  color: #fff;
  border: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}
.model-card-btn:hover { background: var(--color-accent-hover); }

/* ===== Shopping Guide Cards ===== */
.guide-card {
  width: 280px;
  padding: 32px 24px;
  background: var(--color-bg-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth);
}
.guide-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.guide-card-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
}
.guide-card-title { font-size: 17px; font-weight: 600; }
.guide-card-link {
  font-size: 14px;
  color: var(--color-accent);
  font-weight: 500;
}

/* ===== Special Stores Card ===== */
.special-store-card {
  width: 260px;
  padding: 28px 24px;
  background: var(--color-bg-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth);
}
.special-store-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.special-store-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}
.special-store-card-name { font-size: 16px; font-weight: 600; }
.special-store-card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
  flex: 1;
}

/* ===== Store Hero ===== */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg-white);
}
.store-hero-title {
  font-size: clamp(36px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 8px;
}
.store-hero-subtitle {
  font-size: clamp(17px, 2.5vw, 21px);
  color: var(--color-text-secondary);
  font-weight: 450;
  margin-bottom: 32px;
}
.store-hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ===== Promo Banner ===== */
.promo-banner {
  max-width: var(--max-width);
  margin: 0 auto 48px;
  text-align: center;
  padding: 24px;
  background: var(--color-bg);
  border-radius: var(--radius-lg);
}
.promo-banner-text {
  font-size: 16px;
  font-weight: 500;
}

/* ===== Footer ===== */
.footer {
  background: var(--color-bg);
  padding: 48px 24px 32px;
  font-size: 13px;
  color: var(--color-text-secondary);
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-legal {
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 20px;
  margin-bottom: 32px;
  line-height: 1.6;
  font-size: 12px;
  color: var(--color-text-secondary);
}
.footer-legal a { color: var(--color-dark); }
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  padding-bottom: 32px;
  border-bottom: 1px solid var(--color-border);
  margin-bottom: 24px;
}
.footer-col h4 {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-dark);
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 8px; }
.footer-col a { color: var(--color-text-secondary); font-size: 13px; }
.footer-col a:hover { color: var(--color-dark); text-decoration: none; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom-links { display: flex; gap: 20px; }
.footer-bottom-links a { color: var(--color-dark); font-size: 12px; }

/* Footer accordion mobile */
.footer-col-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  width: 100%;
  text-align: left;
  padding: 12px 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-dark);
  letter-spacing: -0.01em;
}

/* ===== Page-specific wrapper ===== */
.page-content { min-height: 60vh; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  :root { --section-pad: 60px; }
  .hero-grid { grid-template-columns: 1fr; }
  .hero-tile { min-height: 420px; padding: 48px 28px 0; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .brand-collab { flex-direction: column; text-align: center; gap: 32px; }
  .brand-collab-content p { max-width: 100%; }
}

@media (max-width: 768px) {
  :root { --section-pad: 48px; }
  .nav-links { display: none; }
  .nav-mobile-toggle { display: block; }
  .section-title { font-size: 28px; }
  .hero-tile { min-height: 380px; padding: 40px 20px 0; }
  .hero-tile-name { font-size: 26px; }
  .product-card { width: 240px; }
  .accessory-card { width: 200px; }
  .help-card { width: 240px; }
  .diff-card { width: 220px; }
  .savings-card { width: 240px; }
  .model-card { width: 220px; }
  .guide-card { width: 240px; }
  .special-store-card { width: 220px; }
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col h4 { display: none; }
  .footer-col-toggle { display: flex; justify-content: space-between; align-items: center; }
  .footer-col-toggle::after {
    content: '+';
    font-size: 18px;
    font-weight: 400;
    transition: transform var(--transition-fast);
  }
  .footer-col.open .footer-col-toggle::after { content: '−'; }
  .footer-col ul { display: none; padding-bottom: 12px; }
  .footer-col.open ul { display: block; }
  .carousel-arrow { display: none; }
  .carousel { padding: 0 16px; margin: 0 -16px; }
  .section-nav-inner { justify-content: flex-start; }
  .store-hero-ctas { flex-direction: column; align-items: center; }
  .product-icon-bar { justify-content: flex-start; flex-wrap: nowrap; }
}

@media (max-width: 480px) {
  .hero-tile { min-height: 320px; }
  .hero-tile-name { font-size: 22px; }
  .hero-tile-ctas { flex-direction: column; gap: 12px; }
  .btn { padding: 10px 20px; font-size: 14px; }
  .footer-bottom { flex-direction: column; text-align: center; }
}
