  border-radius: var(--radius-sm);
  background: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}
.savings-card-name { font-size: 17px; font-weight: 600; }
.savings-card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
  flex: 1;
}
.savings-card-link {
  font-size: 14px;
  color: var(--color-accent);
