}

/* ===== Quick Links ===== */
.quick-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  max-width: var(--max-width);
  margin: 0 auto;
}
.quick-link-btn {
  padding: 12px 28px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
