  transition: all var(--transition-fast);
  text-decoration: none;
}
.quick-link-btn:hover { background: #e8e8ed; text-decoration: none; }

/* ===== Entertainment Tabs ===== */
.entertainment-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}
.entertainment-tab {
  padding: 10px 24px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
  background: transparent;
  color: var(--color-dark);
  border: 1px solid var(--color-border);
  cursor: pointer;
  transition: all var(--transition-fast);
  letter-spacing: -0.01em;
}
.entertainment-tab:hover { background: rgba(0,0,0,0.04); }
.entertainment-tab.active {
  background: var(--color-dark);
  color: #fff;
  border-color: var(--color-dark);
}
.entertainment-content { display: none; }
.entertainment-content.active { display: block; }
.entertainment-card {
  width: 200px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.entertainment-card-image {
  width: 180px;
  height: 260px;
  background: var(--color-bg);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}
.entertainment-card-title {
  font-size: 14px;
  font-weight: 600;
}
.entertainment-card-cta {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-accent);
}

/* ===== Category Page Specific ===== */
.category-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg-white);
}
.category-hero-title {
  font-size: clamp(36px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.1;
  margin-bottom: 12px;
}
.category-hero-subtitle {
  font-size: clamp(17px, 2.5vw, 21px);
  color: var(--color-text-secondary);
  font-weight: 450;
}

/* Sticky section nav */
.section-nav {
  position: sticky;
  top: 48px;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  z-index: 50;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  display: flex;
  gap: 0;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  justify-content: center;
}
.section-nav-link {
  padding: 14px 20px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  letter-spacing: -0.01em;
}
.section-nav-link:hover { color: var(--color-dark); text-decoration: none; }
.section-nav-link.active {
  color: var(--color-dark);
  border-bottom-color: var(--color-dark);
}

