  flex: 1;
}

/* ===== Store Hero ===== */
.store-hero {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--color-bg-white);
}
.store-hero-title {
  font-size: clamp(36px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: -0.025em;
